<script setup lang="ts">
import {reactive,ref,onMounted} from 'vue';import {useRouter,useRoute} from 'vue-router';import {admin,saveAuth,isDemo} from '../../../shared/api';import {useLoad} from '../../../shared/useLoad'
const router=useRouter(),route=useRoute(),form=reactive({username:'',password:'',captchaCode:''}),captcha=ref<{captchaId:string;imageBase64:string}>(),{loading,error,run}=useLoad()
const refresh=async()=>{captcha.value=await admin('GET','/auth/captchas',undefined,{purpose:'admin_login'});form.captchaCode=''}
const submit=()=>run(async()=>{try{const result=await admin<{accessToken:string;expiresIn:number}>('POST','/admin/auth/login',{...form,captchaId:captcha.value?.captchaId});saveAuth('admin',result);const next=String(route.query.redirect||'/');await router.replace(next.startsWith('/')&&!next.startsWith('//')?next:'/')}catch(e){await refresh();throw e}})
onMounted(()=>run(refresh))
</script>
<template><div class="login-page"><form class="login-panel" @submit.prevent="submit"><span class="brand">暖爪</span><p class="eyebrow">STORE ACCESS</p><h1>欢迎回来，店主。</h1><p>照顾好每一只，也照顾好每一份托付。</p><el-alert v-if="isDemo" title="演示账号 admin / WarmPaw2026，图片码 DEMO" type="info" :closable="false"/><el-form label-position="top"><el-form-item label="管理员账号"><el-input v-model="form.username" required autocomplete="username" maxlength="32"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" required type="password" show-password autocomplete="current-password"/></el-form-item><el-form-item label="图片验证码"><div class="captcha-row"><el-input v-model="form.captchaCode" required maxlength="6"/><button type="button" style="border:0;padding:0;background:none" aria-label="刷新验证码" @click="run(refresh)"><img v-if="captcha" :src="captcha.imageBase64" alt="图片验证码"></button></div></el-form-item></el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-button type="primary" native-type="submit" :loading="loading" size="large">登录工作台</el-button></form></div></template>
